"""Edge-case and boundary tests for RateLimiter — generated by bugmagnet."""

import math
import pytest

from rate_limiter import RateLimiter, create_rate_limiter, create_burst_limiter


# ---------------------------------------------------------------------------
# Token bucket – boundary conditions
# ---------------------------------------------------------------------------

class TestTokenBucketBoundaries:
    def test_exactly_max_tokens_allowed(self):
        """A request costing exactly max_tokens should be allowed."""
        rl = RateLimiter(max_tokens=5, refill_rate=1.0)
        assert rl.is_allowed("k", cost=5.0, now=0.0) is True

    def test_one_above_max_tokens_denied(self):
        """A request costing max_tokens + epsilon should be denied immediately."""
        rl = RateLimiter(max_tokens=5, refill_rate=1.0)
        assert rl.is_allowed("k", cost=5.0001, now=0.0) is False

    def test_cost_greater_than_max_tokens_can_never_be_allowed(self):
        """A cost exceeding max_tokens can never be served — wait_time is misleading."""
        rl = RateLimiter(max_tokens=5, refill_rate=1.0)
        # Drain the bucket
        for _ in range(5):
            rl.is_allowed("k", cost=1.0, now=0.0)
        # Even after waiting the suggested time, the request still can't proceed
        wait = rl.get_wait_time("k", cost=10.0, now=0.0)
        assert wait > 0  # Some wait is suggested
        # But cost > max_tokens means it will never be allowed; check that
        later = 0.0 + wait + 1.0
        assert rl.is_allowed("k", cost=10.0, now=later) is False

    def test_fractional_cost_consumes_partial_tokens(self):
        """A fractional cost should reduce tokens by exactly that amount."""
        rl = RateLimiter(max_tokens=10, refill_rate=0.0)
        rl.is_allowed("k", cost=0.5, now=0.0)
        status = rl.get_remaining("k", now=0.0)
        assert status["remaining_tokens"] == pytest.approx(9.5)

    def test_multiple_fractional_costs_accumulate(self):
        rl = RateLimiter(max_tokens=1, refill_rate=0.0)
        assert rl.is_allowed("k", cost=0.4, now=0.0) is True  # 0.6 left
        assert rl.is_allowed("k", cost=0.4, now=0.0) is True  # 0.2 left
        assert rl.is_allowed("k", cost=0.4, now=0.0) is False  # 0.4 > 0.2


# ---------------------------------------------------------------------------
# cost = 0 and negative cost
# ---------------------------------------------------------------------------

class TestZeroAndNegativeCost:
    def test_zero_cost_always_allowed_even_when_exhausted(self):
        """A zero-cost request should always be allowed regardless of token state."""
        rl = RateLimiter(max_tokens=1, refill_rate=0.0)
        rl.is_allowed("k", cost=1.0, now=0.0)  # exhaust
        assert rl.is_allowed("k", cost=0.0, now=0.0) is True

    def test_zero_cost_does_not_reduce_tokens(self):
        rl = RateLimiter(max_tokens=5, refill_rate=0.0)
        rl.is_allowed("k", cost=0.0, now=0.0)
        status = rl.get_remaining("k", now=0.0)
        assert status["remaining_tokens"] == pytest.approx(5.0)

    @pytest.mark.skip(reason="negative cost increases tokens above max_tokens — BUG")
    def test_negative_cost_rejected_or_clamped_BUG(self):
        """
        ROOT CAUSE: is_allowed does not validate that cost >= 0.
                    entry.tokens -= cost with a negative cost adds tokens, potentially
                    exceeding max_tokens with no upper bound check.
        CODE LOCATION: rate_limiter.py:61-62
        PROPOSED FIX: Add a guard at the top of is_allowed:
                      if cost < 0: raise ValueError("cost must be non-negative")
        EXPECTED: ValueError raised for negative cost, or cost treated as 0
        ACTUAL: tokens increase beyond max_tokens (e.g. tokens become 6.0 with max=5)
        """
        rl = RateLimiter(max_tokens=5, refill_rate=0.0)
        rl.is_allowed("k", cost=-1.0, now=0.0)
        status = rl.get_remaining("k", now=0.0)
        assert status["remaining_tokens"] <= 5.0


# ---------------------------------------------------------------------------
# Refill logic
# ---------------------------------------------------------------------------

class TestRefill:
    def test_tokens_refill_over_time(self):
        rl = RateLimiter(max_tokens=10, refill_rate=2.0)
        rl.is_allowed("k", cost=10.0, now=0.0)  # drain
        status = rl.get_remaining("k", now=3.0)  # +6 tokens refilled
        assert status["remaining_tokens"] == pytest.approx(6.0)

    def test_refill_does_not_exceed_max_tokens(self):
        rl = RateLimiter(max_tokens=5, refill_rate=10.0)
        rl.is_allowed("k", cost=1.0, now=0.0)   # 4 left
        status = rl.get_remaining("k", now=100.0)  # would refill 1000 tokens
        assert status["remaining_tokens"] == pytest.approx(5.0)

    def test_refill_with_same_timestamp_does_nothing(self):
        """elapsed == 0 should not change token count."""
        rl = RateLimiter(max_tokens=5, refill_rate=1.0)
        rl.is_allowed("k", cost=3.0, now=10.0)
        status = rl.get_remaining("k", now=10.0)
        assert status["remaining_tokens"] == pytest.approx(2.0)

    def test_refill_with_past_timestamp_does_not_crash_or_refill(self):
        """Passing a now earlier than last_refill should not add tokens."""
        rl = RateLimiter(max_tokens=5, refill_rate=1.0)
        rl.is_allowed("k", cost=3.0, now=100.0)  # last_refill = 100, tokens = 2
        # Calling with an earlier now — elapsed <= 0, no refill
        status = rl.get_remaining("k", now=50.0)
        assert status["remaining_tokens"] == pytest.approx(2.0)

    def test_partial_refill_then_full_request(self):
        rl = RateLimiter(max_tokens=10, refill_rate=1.0)
        rl.is_allowed("k", cost=10.0, now=0.0)  # drain
        # 5 seconds later → 5 tokens refilled
        assert rl.is_allowed("k", cost=5.0, now=5.0) is True
        assert rl.is_allowed("k", cost=1.0, now=5.0) is False


# ---------------------------------------------------------------------------
# get_wait_time
# ---------------------------------------------------------------------------

class TestGetWaitTime:
    def test_zero_wait_when_tokens_available(self):
        rl = RateLimiter(max_tokens=5, refill_rate=1.0)
        assert rl.get_wait_time("k", cost=1.0, now=0.0) == 0.0

    def test_wait_time_reflects_deficit(self):
        rl = RateLimiter(max_tokens=5, refill_rate=1.0)
        rl.is_allowed("k", cost=5.0, now=0.0)   # drain
        # deficit = 3, refill_rate = 1 → wait = 3s
        wait = rl.get_wait_time("k", cost=3.0, now=0.0)
        assert wait == pytest.approx(3.0)

    def test_wait_time_exactly_when_tokens_equal_cost(self):
        rl = RateLimiter(max_tokens=5, refill_rate=1.0)
        rl.is_allowed("k", cost=4.0, now=0.0)  # 1 token left
        assert rl.get_wait_time("k", cost=1.0, now=0.0) == 0.0

    def test_wait_time_for_new_key_with_full_bucket_is_zero(self):
        rl = RateLimiter(max_tokens=5, refill_rate=1.0)
        assert rl.get_wait_time("brand_new_key", cost=5.0, now=0.0) == 0.0

    @pytest.mark.skip(reason="get_wait_time divides by refill_rate=0 → ZeroDivisionError — BUG")
    def test_get_wait_time_zero_refill_rate_BUG(self):
        """
        ROOT CAUSE: get_wait_time computes `deficit / self.refill_rate` without
                    guarding against refill_rate == 0, causing ZeroDivisionError.
        CODE LOCATION: rate_limiter.py:81
        PROPOSED FIX: Return math.inf (or raise ValueError) when refill_rate == 0
                      and tokens are insufficient:
                      if self.refill_rate == 0:
                          return math.inf if entry.tokens < cost else 0.0
        EXPECTED: Returns math.inf or raises a descriptive ValueError
        ACTUAL: ZeroDivisionError: float division by zero
        """
        rl = RateLimiter(max_tokens=5, refill_rate=0.0)
        rl.is_allowed("k", cost=5.0, now=0.0)  # drain
        result = rl.get_wait_time("k", cost=1.0, now=0.0)
        assert result == math.inf

    @pytest.mark.skip(reason="create_rate_limiter(0) produces refill_rate=0; get_wait_time then ZeroDivisionError — BUG")
    def test_create_rate_limiter_zero_rpm_wait_time_BUG(self):
        """
        ROOT CAUSE: create_rate_limiter(0) sets refill_rate=0/60=0.0.
                    Downstream call to get_wait_time on exhausted bucket triggers
                    ZeroDivisionError at rate_limiter.py:81.
        CODE LOCATION: rate_limiter.py:81 (division), rate_limiter.py:125 (factory)
        PROPOSED FIX: Guard refill_rate==0 in get_wait_time (see above), or
                      raise ValueError in the factory if requests_per_minute <= 0.
        EXPECTED: Returns math.inf or factory raises ValueError
        ACTUAL: ZeroDivisionError
        """
        rl = create_rate_limiter(0)
        rl.is_allowed("k", cost=1.0, now=0.0)  # with max_tokens=0 this is also False
        result = rl.get_wait_time("k", cost=1.0, now=0.0)
        assert result == math.inf


# ---------------------------------------------------------------------------
# Sliding window – boundary conditions
# ---------------------------------------------------------------------------

class TestSlidingWindowBoundaries:
    def test_timestamp_exactly_at_cutoff_is_excluded(self):
        """_clean_window uses ts > cutoff (strict), so ts == cutoff is removed."""
        rl = RateLimiter(max_tokens=10, refill_rate=0.0, window_seconds=60.0)
        rl.is_allowed("k", cost=1.0, now=0.0)    # ts=0.0, cutoff at now=60 is 0.0
        status = rl.get_remaining("k", now=60.0)
        # ts=0.0 is NOT > cutoff=0.0, so it should be removed
        assert status["requests_in_window"] == 0

    def test_timestamp_one_epsilon_after_cutoff_is_included(self):
        rl = RateLimiter(max_tokens=10, refill_rate=0.0, window_seconds=60.0)
        rl.is_allowed("k", cost=1.0, now=0.001)   # ts=0.001, cutoff at now=60 is 0.0
        status = rl.get_remaining("k", now=60.0)
        assert status["requests_in_window"] == 1

    def test_window_counts_only_requests_within_window(self):
        rl = RateLimiter(max_tokens=10, refill_rate=0.0, window_seconds=10.0)
        # 3 requests at t=0, 2 requests at t=5
        for _ in range(3):
            rl.is_allowed("k", cost=1.0, now=0.0)
        for _ in range(2):
            rl.is_allowed("k", cost=1.0, now=5.0)
        # At t=11, window covers (1, 11], so only the t=5 requests count
        status = rl.get_remaining("k", now=11.0)
        assert status["requests_in_window"] == 2

    def test_requests_in_window_resets_after_full_window_elapses(self):
        rl = RateLimiter(max_tokens=10, refill_rate=10.0, window_seconds=5.0)
        for _ in range(5):
            rl.is_allowed("k", cost=1.0, now=0.0)
        status = rl.get_remaining("k", now=6.0)
        assert status["requests_in_window"] == 0


# ---------------------------------------------------------------------------
# Key isolation
# ---------------------------------------------------------------------------

class TestKeyIsolation:
    def test_different_keys_are_independent(self):
        rl = RateLimiter(max_tokens=2, refill_rate=0.5)
        rl.is_allowed("a", cost=2.0, now=0.0)  # drain "a"
        assert rl.is_allowed("a", now=0.0) is False
        assert rl.is_allowed("b", now=0.0) is True

    def test_new_key_gets_full_bucket(self):
        rl = RateLimiter(max_tokens=5, refill_rate=1.0)
        rl.is_allowed("existing", cost=5.0, now=0.0)
        # New key should start with full tokens
        status = rl.get_remaining("fresh", now=0.0)
        assert status["remaining_tokens"] == pytest.approx(5.0)

    def test_get_all_keys_reflects_accessed_keys(self):
        rl = RateLimiter(max_tokens=5, refill_rate=1.0)
        rl.is_allowed("alice", now=0.0)
        rl.is_allowed("bob", now=0.0)
        keys = rl.get_all_keys()
        assert set(keys) == {"alice", "bob"}

    def test_get_wait_time_on_new_key_creates_entry_side_effect(self):
        """get_wait_time creates an entry as a side effect of _get_or_create."""
        rl = RateLimiter(max_tokens=5, refill_rate=1.0)
        rl.get_wait_time("ghost", now=0.0)
        assert "ghost" in rl.get_all_keys()


# ---------------------------------------------------------------------------
# cleanup_expired
# ---------------------------------------------------------------------------

class TestCleanupExpired:
    def test_removes_idle_entries_beyond_twice_window(self):
        rl = RateLimiter(max_tokens=5, refill_rate=1.0, window_seconds=60.0)
        rl.is_allowed("k", now=0.0)
        removed = rl.cleanup_expired(now=121.0)  # 121 > 2*60
        assert removed == 1
        assert "k" not in rl.get_all_keys()

    def test_does_not_remove_recently_active_entry(self):
        rl = RateLimiter(max_tokens=5, refill_rate=1.0, window_seconds=60.0)
        rl.is_allowed("k", now=0.0)
        removed = rl.cleanup_expired(now=100.0)  # 100 < 2*60
        assert removed == 0
        assert "k" in rl.get_all_keys()

    def test_cleanup_at_exact_threshold_boundary(self):
        """Entry idle for exactly 2*window should be removed (> threshold is False)."""
        rl = RateLimiter(max_tokens=5, refill_rate=1.0, window_seconds=60.0)
        rl.is_allowed("k", now=0.0)
        # now - last_refill == 120 exactly; condition is > threshold, so NOT removed
        removed = rl.cleanup_expired(now=120.0)
        assert removed == 0

    def test_cleanup_just_above_threshold_removes_entry(self):
        rl = RateLimiter(max_tokens=5, refill_rate=1.0, window_seconds=60.0)
        rl.is_allowed("k", now=0.0)
        removed = rl.cleanup_expired(now=120.0001)
        assert removed == 1

    def test_accessing_entry_via_get_remaining_resets_expiry_clock(self):
        """get_remaining calls _refill which updates last_refill, resetting expiry."""
        rl = RateLimiter(max_tokens=5, refill_rate=1.0, window_seconds=60.0)
        rl.is_allowed("k", now=0.0)
        # Access at t=100 (still within 2*60=120 window), resetting last_refill to 100
        rl.get_remaining("k", now=100.0)
        # Now the clock is from t=100; 121 - 100 = 21 < 120, should NOT be removed
        removed = rl.cleanup_expired(now=121.0)
        assert removed == 0

    def test_cleanup_returns_zero_when_nothing_expired(self):
        rl = RateLimiter(max_tokens=5, refill_rate=1.0, window_seconds=60.0)
        assert rl.cleanup_expired(now=0.0) == 0

    def test_cleanup_multiple_entries(self):
        rl = RateLimiter(max_tokens=5, refill_rate=1.0, window_seconds=10.0)
        rl.is_allowed("a", now=0.0)
        rl.is_allowed("b", now=0.0)
        rl.is_allowed("c", now=15.0)  # added later, less idle
        removed = rl.cleanup_expired(now=21.0)  # 21 > 2*10; a and b: 21>20; c: 6<=20
        assert removed == 2


# ---------------------------------------------------------------------------
# get_remaining
# ---------------------------------------------------------------------------

class TestGetRemaining:
    def test_all_keys_present_in_result(self):
        rl = RateLimiter(max_tokens=10, refill_rate=1.0, window_seconds=30.0)
        rl.is_allowed("k", cost=3.0, now=0.0)
        status = rl.get_remaining("k", now=0.0)
        assert set(status.keys()) == {
            "remaining_tokens", "requests_in_window", "window_seconds", "resets_at"
        }

    def test_resets_at_is_future_timestamp(self):
        """resets_at should be in the future relative to now."""
        rl = RateLimiter(max_tokens=10, refill_rate=1.0, window_seconds=60.0)
        rl.is_allowed("k", now=100.0)
        status = rl.get_remaining("k", now=100.0)
        assert status["resets_at"] > 100.0

    def test_window_seconds_matches_constructor(self):
        rl = RateLimiter(max_tokens=5, refill_rate=1.0, window_seconds=120.0)
        status = rl.get_remaining("k", now=0.0)
        assert status["window_seconds"] == 120.0

    def test_requests_in_window_increments_per_allowed_request(self):
        rl = RateLimiter(max_tokens=5, refill_rate=1.0)
        for i in range(3):
            rl.is_allowed("k", cost=1.0, now=float(i))
        status = rl.get_remaining("k", now=3.0)
        assert status["requests_in_window"] == 3

    def test_denied_request_does_not_increment_requests_in_window(self):
        """Denied requests should not appear in the window count."""
        rl = RateLimiter(max_tokens=1, refill_rate=0.0)
        rl.is_allowed("k", cost=1.0, now=0.0)   # allowed
        rl.is_allowed("k", cost=1.0, now=0.0)   # denied
        status = rl.get_remaining("k", now=0.0)
        assert status["requests_in_window"] == 1


# ---------------------------------------------------------------------------
# Factory helpers
# ---------------------------------------------------------------------------

class TestFactories:
    def test_create_rate_limiter_allows_rpm_requests_per_minute(self):
        rl = create_rate_limiter(60)
        allowed = sum(1 for i in range(60) if rl.is_allowed("k", now=float(i)))
        # All 60 should succeed; they each arrive 1s apart (refill_rate=1/s)
        # But first request starts with full bucket of 60; each +1 token/sec consumed
        assert allowed == 60

    def test_create_rate_limiter_60rpm_exhausted_at_t0(self):
        rl = create_rate_limiter(10)
        # Burn through all tokens at t=0
        results = [rl.is_allowed("k", now=0.0) for _ in range(11)]
        assert results[:10] == [True] * 10
        assert results[10] is False

    def test_create_burst_limiter_allows_burst(self):
        rl = create_burst_limiter(burst_size=10, sustained_per_second=2.0)
        results = [rl.is_allowed("k", now=0.0) for _ in range(10)]
        assert all(results)

    def test_create_burst_limiter_denies_beyond_burst(self):
        rl = create_burst_limiter(burst_size=5, sustained_per_second=1.0)
        for _ in range(5):
            rl.is_allowed("k", now=0.0)
        assert rl.is_allowed("k", now=0.0) is False

    def test_create_burst_limiter_sustained_refill(self):
        rl = create_burst_limiter(burst_size=5, sustained_per_second=1.0)
        for _ in range(5):
            rl.is_allowed("k", now=0.0)
        # 3 seconds later → 3 tokens refilled
        assert rl.is_allowed("k", cost=3.0, now=3.0) is True


# ---------------------------------------------------------------------------
# Concurrent-style multi-step sequences
# ---------------------------------------------------------------------------

class TestMultiStepSequences:
    def test_drain_wait_and_refill_sequence(self):
        rl = RateLimiter(max_tokens=5, refill_rate=1.0)
        for _ in range(5):
            rl.is_allowed("k", cost=1.0, now=0.0)
        # Ask how long to wait for next request
        wait = rl.get_wait_time("k", cost=1.0, now=0.0)
        assert wait == pytest.approx(1.0)
        # After waiting, request should succeed
        assert rl.is_allowed("k", cost=1.0, now=wait) is True

    def test_rapid_sequence_with_interleaved_refills(self):
        rl = RateLimiter(max_tokens=3, refill_rate=3.0)  # 3 tokens/sec
        assert rl.is_allowed("k", cost=3.0, now=0.0) is True    # drain
        assert rl.is_allowed("k", cost=1.0, now=0.5) is True    # +1.5 refilled, 0.5 used
        assert rl.is_allowed("k", cost=1.0, now=0.5) is False   # 0 remaining

    def test_two_keys_race_for_shared_limiter(self):
        rl = RateLimiter(max_tokens=2, refill_rate=1.0)
        assert rl.is_allowed("user_a", cost=2.0, now=0.0) is True
        assert rl.is_allowed("user_b", cost=2.0, now=0.0) is True
        assert rl.is_allowed("user_a", cost=1.0, now=0.0) is False
        assert rl.is_allowed("user_b", cost=1.0, now=0.0) is False
